export const getGetMembresIdHistoriqueUrl = (id: string,
    params?: GetMembresIdHistoriqueParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/membres/${id}/historique?${stringifiedParams}` : `/membres/${id}/historique`
}

